import React, { useEffect, useState } from 'react';
import LeaveService from '../Services/LeaveService';

const STATUS_CONFIG = {
  APPROVED: {
    color: '#0d7a4e',
    bg: '#e6f7ef',
    border: '#a3dfc0',
    dot: '#22c77a',
    label: 'Approved',
  },
  REJECTED: {
    color: '#b91c1c',
    bg: '#fef2f2',
    border: '#fca5a5',
    dot: '#ef4444',
    label: 'Rejected',
  },
  PENDING: {
    color: '#92610a',
    bg: '#fffbeb',
    border: '#fcd34d',
    dot: '#f59e0b',
    label: 'Pending',
  },
};

const LEAVE_ICONS = {
  'sick leave': '🤒',
  'holiday leave': '🌴',
  'earned leave': '⭐',
};

function StatusBadge({ status }) {
  const cfg = STATUS_CONFIG[status] || STATUS_CONFIG.PENDING;
  return (
    <span style={{
      display: 'inline-flex',
      alignItems: 'center',
      gap: '6px',
      padding: '4px 10px',
      borderRadius: '20px',
      fontSize: '12px',
      fontWeight: '600',
      color: cfg.color,
      background: cfg.bg,
      border: `1px solid ${cfg.border}`,
      letterSpacing: '0.2px',
    }}>
      <span style={{
        width: '6px', height: '6px',
        borderRadius: '50%',
        background: cfg.dot,
        display: 'inline-block',
        flexShrink: 0,
      }} />
      {cfg.label}
    </span>
  );
}

function EmptyState() {
  return (
    <div style={{
      textAlign: 'center',
      padding: '56px 24px',
      color: '#a0aabf',
    }}>
      <div style={{
        width: '64px', height: '64px',
        borderRadius: '16px',
        background: '#f4f6fb',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        margin: '0 auto 16px',
      }}>
        <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#c5cce0" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
          <rect x="3" y="4" width="18" height="18" rx="2" ry="2"/>
          <line x1="16" y1="2" x2="16" y2="6"/>
          <line x1="8" y1="2" x2="8" y2="6"/>
          <line x1="3" y1="10" x2="21" y2="10"/>
        </svg>
      </div>
      <p style={{ margin: 0, fontSize: '14px', fontWeight: '600', color: '#6b7694' }}>No leaves found</p>
      <p style={{ margin: '4px 0 0', fontSize: '13px' }}>Your leave requests will appear here</p>
    </div>
  );
}

function ViewMyLeaves({ user }) {
  const [leaves, setLeaves] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('ALL');

  useEffect(() => {
    LeaveService.getLeavesByEmployee(user.id)
      .then((res) => { setLeaves(res.data); setLoading(false); })
      .catch((err) => { console.log(err); setLoading(false); });
  }, []);

  const filtered = filter === 'ALL' ? leaves : leaves.filter(l => l.status === filter);

  const counts = {
    ALL: leaves.length,
    APPROVED: leaves.filter(l => l.status === 'APPROVED').length,
    PENDING: leaves.filter(l => l.status === 'PENDING').length,
    REJECTED: leaves.filter(l => l.status === 'REJECTED').length,
  };

  const formatDate = (dateStr) => {
    if (!dateStr) return '—';
    const d = new Date(dateStr);
    return d.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });
  };

  const tabStyle = (active) => ({
    padding: '6px 14px',
    borderRadius: '6px',
    fontSize: '12px',
    fontWeight: '600',
    cursor: 'pointer',
    border: 'none',
    background: active ? '#1a1f36' : 'transparent',
    color: active ? '#fff' : '#6b7694',
    transition: 'all 0.15s',
    fontFamily: "'DM Sans', 'Segoe UI', sans-serif",
    letterSpacing: '0.2px',
  });

  return (
    <div style={{
      background: '#fff',
      borderRadius: '16px',
      boxShadow: '0 4px 24px rgba(26,31,54,0.08)',
      overflow: 'hidden',
      fontFamily: "'DM Sans', 'Segoe UI', sans-serif",
    }}>

      {/* Card Header */}
      <div style={{
        background: 'linear-gradient(135deg, #1a1f36 0%, #2d3561 100%)',
        padding: '24px 28px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
          <div style={{
            width: '32px', height: '32px', borderRadius: '8px',
            background: 'rgba(255,255,255,0.15)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
          }}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
              <rect x="3" y="4" width="18" height="18" rx="2" ry="2"/>
              <line x1="16" y1="2" x2="16" y2="6"/>
              <line x1="8" y1="2" x2="8" y2="6"/>
              <line x1="3" y1="10" x2="21" y2="10"/>
            </svg>
          </div>
          <div>
            <h2 style={{ margin: 0, fontSize: '16px', fontWeight: '700', color: '#fff', letterSpacing: '-0.2px' }}>
              My Leaves
            </h2>
            <p style={{ margin: 0, fontSize: '12px', color: 'rgba(255,255,255,0.6)', marginTop: '2px' }}>
              {leaves.length} total request{leaves.length !== 1 ? 's' : ''}
            </p>
          </div>
        </div>

        {/* Summary Pills */}
        <div style={{ display: 'flex', gap: '8px' }}>
          {[
            { key: 'APPROVED', color: '#22c77a', bg: 'rgba(34,199,122,0.15)' },
            { key: 'PENDING', color: '#f59e0b', bg: 'rgba(245,158,11,0.15)' },
            { key: 'REJECTED', color: '#ef4444', bg: 'rgba(239,68,68,0.15)' },
          ].map(({ key, color, bg }) => (
            <div key={key} style={{
              padding: '4px 10px',
              borderRadius: '20px',
              background: bg,
              fontSize: '12px',
              fontWeight: '600',
              color,
              display: 'flex',
              alignItems: 'center',
              gap: '5px',
            }}>
              <span style={{ width: '5px', height: '5px', borderRadius: '50%', background: color, display: 'inline-block' }} />
              {counts[key]}
            </div>
          ))}
        </div>
      </div>

      {/* Filter Tabs */}
      <div style={{
        padding: '16px 24px',
        borderBottom: '1px solid #f0f2f8',
        display: 'flex',
        gap: '4px',
        background: '#fafbfd',
      }}>
        {['ALL', 'APPROVED', 'PENDING', 'REJECTED'].map((tab) => (
          <button
            key={tab}
            onClick={() => setFilter(tab)}
            style={tabStyle(filter === tab)}
          >
            {tab === 'ALL' ? `All (${counts.ALL})` : `${tab.charAt(0) + tab.slice(1).toLowerCase()} (${counts[tab]})`}
          </button>
        ))}
      </div>

      {/* Table */}
      {loading ? (
        <div style={{ padding: '48px', textAlign: 'center', color: '#a0aabf', fontSize: '14px' }}>
          Loading leave records...
        </div>
      ) : filtered.length === 0 ? (
        <EmptyState />
      ) : (
        <div style={{ overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ background: '#f7f9fc' }}>
                {['Type', 'Duration', 'Days', 'Status'].map((h) => (
                  <th key={h} style={{
                    padding: '11px 20px',
                    textAlign: 'left',
                    fontSize: '11px',
                    fontWeight: '700',
                    color: '#8892aa',
                    textTransform: 'uppercase',
                    letterSpacing: '0.7px',
                    borderBottom: '1px solid #edf0f7',
                  }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {filtered.map((l, idx) => {
                const icon = LEAVE_ICONS[l.leaveType?.toLowerCase()] || '📋';
                const start = new Date(l.startDate);
                const end = new Date(l.endDate);
                const days = Math.round((end - start) / (1000 * 60 * 60 * 24)) + 1;

                return (
                  <tr
                    key={l.lid}
                    style={{
                      borderBottom: idx === filtered.length - 1 ? 'none' : '1px solid #f0f2f8',
                      transition: 'background 0.15s',
                    }}
                    onMouseEnter={e => e.currentTarget.style.background = '#fafbfd'}
                    onMouseLeave={e => e.currentTarget.style.background = 'transparent'}
                  >
                    {/* Type */}
                    <td style={{ padding: '14px 20px' }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                        <div style={{
                          width: '34px', height: '34px', borderRadius: '8px',
                          background: '#f0f4fb',
                          display: 'flex', alignItems: 'center', justifyContent: 'center',
                          fontSize: '16px', flexShrink: 0,
                        }}>
                          {icon}
                        </div>
                        <div>
                          <div style={{ fontSize: '13px', fontWeight: '600', color: '#1a1f36', textTransform: 'capitalize' }}>
                            {l.leaveType}
                          </div>
                          <div style={{ fontSize: '11px', color: '#a0aabf', marginTop: '1px' }}>
                            ID: {l.lid}
                          </div>
                        </div>
                      </div>
                    </td>

                    {/* Duration */}
                    <td style={{ padding: '14px 20px' }}>
                      <div style={{ fontSize: '13px', color: '#1a1f36', fontWeight: '500' }}>
                        {formatDate(l.startDate)}
                      </div>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '4px', margin: '2px 0' }}>
                        <div style={{ width: '20px', height: '1px', background: '#c5cce0' }} />
                        <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="#c5cce0" strokeWidth="2.5" strokeLinecap="round">
                          <line x1="5" y1="12" x2="19" y2="12"/>
                          <polyline points="12,5 19,12 12,19"/>
                        </svg>
                      </div>
                      <div style={{ fontSize: '13px', color: '#1a1f36', fontWeight: '500' }}>
                        {formatDate(l.endDate)}
                      </div>
                    </td>

                    {/* Days */}
                    <td style={{ padding: '14px 20px' }}>
                      <span style={{
                        display: 'inline-block',
                        padding: '3px 10px',
                        borderRadius: '6px',
                        background: '#f0f4fb',
                        fontSize: '13px',
                        fontWeight: '700',
                        color: '#3b4784',
                      }}>
                        {days}d
                      </span>
                    </td>

                    {/* Status */}
                    <td style={{ padding: '14px 20px' }}>
                      <StatusBadge status={l.status} />
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {/* Footer */}
      {filtered.length > 0 && (
        <div style={{
          padding: '12px 24px',
          borderTop: '1px solid #f0f2f8',
          background: '#fafbfd',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
        }}>
          <span style={{ fontSize: '12px', color: '#a0aabf' }}>
            Showing {filtered.length} of {leaves.length} records
          </span>
          <span style={{ fontSize: '12px', color: '#a0aabf' }}>
            Last updated: {new Date().toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' })}
          </span>
        </div>
      )}

    </div>
  );
}

export default ViewMyLeaves;
